"""Bivariate factorisation over GF(2) of Laurent polynomials (sets of exponent pairs)."""
import sys, itertools
sys.path.insert(0,'tools')
import sympy
z=sympy.Symbol('z')
def norm(P):
    # P: set of (i,j); shift to min exponents 0
    if not P: return frozenset()
    mi=min(i for i,j in P); mj=min(j for i,j in P)
    return frozenset((i-mi,j-mj) for i,j in P)
def mul(P,Q):
    out=set()
    for a in P:
        for b in Q:
            s=(a[0]+b[0],a[1]+b[1]); out^={s}
    return frozenset(out)
def divide(P,Q):
    """exact division of polynomials (nonneg exponents) over GF2; returns quotient or None"""
    P=set(P); Q=sorted(Q)  # lex order by (i,j)
    lead=max(Q)
    quo=set()
    while P:
        l=max(P)
        d=(l[0]-lead[0], l[1]-lead[1])
        if d[0]<0 or d[1]<0: return None
        quo^={d}
        for q in Q:
            P^={(q[0]+d[0],q[1]+d[1])}
    # check nonneg
    return frozenset(quo)
def factor(P):
    P=norm(P)
    if len(P)<=1: return []
    dx=max(i for i,j in P); N=dx+1
    u=sympy.Poly(sum(z**(i+N*j) for i,j in P),z,modulus=2)
    fl=[]
    for g,e in u.factor_list()[1]: fl+=[g]*e
    n=len(fl)
    for k in range(1,n//2+1):
        for S in itertools.combinations(range(n),k):
            g=sympy.Poly(1,z,modulus=2)
            for i in S: g=g*fl[i]
            G=frozenset((e%N,e//N) for (e,),c in g.terms() if int(c)%2)
            G=norm(G)
            if len(G)<=1: continue
            q=divide(P,G)
            if q is not None and mul(q,G)==P:
                return factor(G)+factor(q)
    return [P]
def show(P):
    return '+'.join(f'x^{i}y^{j}' for i,j in sorted(P))
if __name__=='__main__':
    from family import rule
    ids=[int(x) for x in sys.argv[1:]]
    for i in ids:
        fs=factor(rule(i))
        print(i, len(fs), [ (len(F), max(a for a,b in F), max(b for a,b in F)) for F in fs])
        for F in fs: print('   ', show(F))
