"""Refined chance model: per-class empirical cube rates over the square family."""
import sys, json, math, functools; sys.path.insert(0,'tools'); sys.path.insert(0,'.')
import numpy as np, sympy
import chance
from family import ORBITS, rule
from halffrob import sord, ord2

def minpoly_t(m):
    T=sympy.Symbol('t')
    D=[sympy.Poly(0,T,modulus=2), sympy.Poly(T,T,modulus=2), sympy.Poly(T**2,T,modulus=2)]
    for e in range(3,m): D.append(sympy.Poly(T,T,modulus=2)*D[-1]+D[-2])
    # Psi-ish: t_1 is a root of D_m(t) / t ... take z^-((m-1)/2) Phi_m? use D_m(t) = t * prod Psi^2;
    # minimal polynomial of t_1: factor of (1 + sum_{e=1}^{(m-1)/2} D_e) for prime m; general: factor D_m(t)/t
    # and pick a factor whose root has the right order: test via t_j distinctness
    P=sympy.Poly(1,T,modulus=2)
    for e in range(1,(m+1)//2): P=P+D[e]   # = z^{-(m-1)/2}(1+z+...+z^{m-1}) in t
    for g,_ in P.factor_list()[1]:
        if g.degree()==sord(m):
            # check it's for a primitive m-th root: the polynomial for divisor m' < m would give smaller order
            return sum((int(c)%2)<<e for (e,),c in g.terms()), g.degree()
    raise ValueError

class VF:
    def __init__(self,m):
        self.m=m; self.mod,self.s=minpoly_t(m)
    def mul(self,a,b):
        r=0; s=self.s
        while b:
            if b&1: r^=a
            b>>=1; a<<=1
            if a>>s&1: a^=self.mod
        return r
    def vmul(self,A,B):
        A=A.copy(); B=B.copy(); R=np.zeros_like(A); s=self.s
        for _ in range(s):
            R^=np.where(B&1,A,0); B>>=1; A<<=1
            A^=np.where((A>>s)&1,self.mod,0)
        return R
    def vpow(self,A,e):
        R=np.ones_like(A); 
        while e:
            if e&1: R=self.vmul(R,A)
            A=self.vmul(A,A); e>>=1
        return R

def analyse(m,q=3):
    V=VF(m); s=V.s
    # check t_1 generates: t_j values
    t=[0]*m; t[1]=2
    for j in range(2,m): t[j]=V.mul(2,t[j-1])^t[j-2]
    t[0]=0
    assert t[m-1]==2, 'bad'
    def orbval(o,j,k):
        i,l=o
        if (i,l)==(0,0): return 1
        if l==0: return t[i*j%m]^t[i*k%m]
        if i==l: return V.mul(t[i*j%m],t[i*k%m])
        return V.mul(t[i*j%m],t[l*k%m])^V.mul(t[l*j%m],t[i*k%m])
    sym=chance.symmetries(rule(1),m)   # generic: D4 x powers of 2 (rule 1 = self has all; restrict to D4 ones)
    # use a generic rule's symmetries: rule with only lattice symmetry
    sym=chance.symmetries(rule(0b111111111111111),m)
    part=chance.partition(m,sym)
    reps=[p[0] for p in part]; deg=[p[2] for p in part]
    N=2**s-1
    ov=np.array([[orbval(o,j,k) for (j,k) in reps] for o in ORBITS],dtype=np.int64)
    A=np.zeros((1<<15,len(reps)),dtype=np.int64)
    for i in range(15):
        bit=1<<i; A[bit:2*bit]=A[:bit]^ov[i]
    if N%q: return None
    C=V.vpow(A.reshape(-1),N//q).reshape(A.shape)
    cube=(C==1)&(A!=0)
    free=[c for c in range(len(reps)) if chance.cube_chance(deg[c],m)<1]
    nz=A!=0
    p=np.array([cube[nz[:,c],c].mean() if nz[:,c].any() else 1 for c in range(len(reps))])
    pmodel=np.array([chance.cube_chance(deg[c],m) for c in range(len(reps))])
    allc=((~nz)|cube).all(axis=1); allc[0]=False
    E_ref=0.0; E_mod=0.0
    for r in range(1,1<<15):
        cs=[c for c in free if nz[r,c]]
        if not cs: continue
        E_ref+=math.prod(p[c] for c in cs); E_mod+=math.prod(pmodel[c] for c in cs)
    return dict(m=m,reps=reps,deg=deg,free=free,p=p,pmodel=pmodel,E_ref=E_ref,E_model=E_mod,allcube=int(allc.sum()),allc=allc)
if __name__=='__main__':
    for m in [int(x) for x in sys.argv[1:]]:
        R=analyse(m)
        print('m',m,'classes',len(R['reps']),'free',len(R['free']),'all-cube rules',R['allcube'],
              'E_model %.2f'%R['E_model'],'E_refined %.2f'%R['E_ref'])
        for c in R['free']:
            print('   ',R['reps'][c],'deg',R['deg'][c],'p_emp %.3f'%R['p'][c],'p_model %.3f'%R['pmodel'][c])
