import sys, math; sys.path.insert(0,'tools'); sys.path.insert(0,'.')
from sympy import ZZ, totient
from sympy.polys import galoistools as gt
from family import rule
from halffrob import _psi, _dickson
import mechanism as M
m=int(sys.argv[1]) if len(sys.argv)>1 else 37
ids=[int(x) for x in sys.argv[2:]] or [4850,5972,13822,22064,25183,27390,28586]
PSI={}
for e in range(3,4000,2):
    if math.gcd(e,m)==1:
        PSI.setdefault(_psi(e),e)
def line_H(f,c1,c2):
    co={}
    for x,y in f:
        e=x*c1+y*c2; co[e]=co.get(e,0)^1
    H=0
    for e,v in co.items():
        if v and e>=0:
            H^= 1 if e==0 else _dickson(e)
    return H
def good(H,q=3):
    if H==0: return True
    for g,n in gt.gf_factor(M._to_list(H),2,ZZ)[1]:
        if n%q==0: continue
        pi=M._from_list(g)
        if pi==0b10 or pi in PSI: continue
        return False
    return True
def reps(m):
    seen={}; 
    for u in range(m):
        key=min(u,(-u)%m, pow(u,-1,m) if u else 0, (-pow(u,-1,m))%m if u else 0)
        seen.setdefault(key,(1,u))
    return list(seen.values())+[]
def cen(x): 
    x%=m; return x-m if x>m//2 else x
for i in ids:
    f=rule(i); out=[]
    for (a,u) in reps(m):
        ok=None
        for lam in range(1,m):
            c=(cen(lam*a),cen(lam*u))
            if good(line_H(f,*c)): ok=c; break
        out.append(((a,u),ok))
    print(i, sum(1 for _,o in out if o), '/',len(out), [k for k,o in out if not o])
