"""Generate the polynomial part of proofs/LatticeProofs/Pilot.lean: for each target D = U * g^3,
the offsets, the Laurent polynomial in x xi y yi, and the identity with a linear_combination
certificate."""
import sys; sys.path.insert(0,'tools')
import sympy
from family import rule
x,xi,y,yi=sympy.symbols('x xi y yi')
a=x+xi; b=y+yi
U={'sum':a+b,'prod':a*b,'psi3':(a+1)*(b+1)}
G={'n':a+b+1,'d':a*b+1,'m':a*b+a+b}
ULEAN={'sum':'(x + xi + (y + yi))','prod':'((x + xi) * (y + yi))','psi3':'((x + xi + 1) * (y + yi + 1))'}
GLEAN={'n':'(x + xi + (y + yi) + 1)','d':'((x + xi) * (y + yi) + 1)','m':'((x + xi) * (y + yi) + (x + xi) + (y + yi))'}
TARGETS={1112:('sum','n'),2436:('prod','n'),3461:('psi3','n'),10498:('sum','d'),17056:('prod','d'),
         26883:('psi3','d'),13584:('sum','m'),28944:('prod','m'),18246:('psi3','m')}
def mono(i,j):
    px = x**i if i>=0 else xi**(-i)
    py = y**j if j>=0 else yi**(-j)
    return px*py
def lean_mono(i,j):
    parts=[]
    if i>0: parts.append('x' if i==1 else f'x^{i}')
    if i<0: parts.append('xi' if i==-1 else f'xi^{-i}')
    if j>0: parts.append('y' if j==1 else f'y^{j}')
    if j<0: parts.append('yi' if j==-1 else f'yi^{-j}')
    return '*'.join(parts) if parts else '1'
def certificate(P):
    """P in Z[x,xi,y,yi]: return e1,e2,e3 with P = 2 e1 + e2 (x xi - 1) + e3 (y yi - 1)."""
    P=sympy.Poly(sympy.expand(P),x,xi,y,yi)
    e2=0; rest={}
    for (A,B,C,D),c in P.terms():
        k=min(A,B)
        S=sum((x*xi)**i for i in range(k))
        e2+= c*x**(A-k)*xi**(B-k)*y**C*yi**D*S
        key=(A-k,B-k,C,D); rest[key]=rest.get(key,0)+c
    e3=0; rest2={}
    for (A,B,C,D),c in rest.items():
        k=min(C,D)
        S=sum((y*yi)**i for i in range(k))
        e3+= c*x**A*xi**B*y**(C-k)*yi**(D-k)*S
        key=(A,B,C-k,D-k); rest2[key]=rest2.get(key,0)+c
    e1=0
    for (A,B,C,D),c in rest2.items():
        assert c%2==0,(A,B,C,D,c)
        e1+= (c//2)*x**A*xi**B*y**C*yi**D
    chk=sympy.expand(2*e1+e2*(x*xi-1)+e3*(y*yi-1)-P.as_expr())
    assert chk==0
    return sympy.expand(e1),sympy.expand(e2),sympy.expand(e3)
def lean_expr(E):
    s=str(E).replace('**','^')
    return s
out=[]
for rid,(u,g) in TARGETS.items():
    f=sorted(rule(rid))
    offs=', '.join(f'({i}, {j})' for i,j in f)
    poly=' + '.join(lean_mono(i,j) for i,j in f)
    D=sum(mono(i,j) for i,j in f)
    P=D-U[u]*G[g]**3
    e1,e2,e3=certificate(P)
    out.append(f"""/-- Family rule {rid}. -/
def r{rid}Offsets : Finset (ℤ × ℤ) :=
  {{{offs}}}

/-- Rule {rid}'s Laurent polynomial, xi = 1/x, yi = 1/y. -/
def r{rid}Poly (x xi y yi : R) : R :=
  {poly}

/-- **Rule {rid} = U * g^3** in characteristic 2. -/
theorem r{rid}_identity (h2 : (2 : R) = 0) (x xi y yi : R) (hx : x * xi = 1) (hy : y * yi = 1) :
    r{rid}Poly x xi y yi = {ULEAN[u]} * {GLEAN[g]} ^ 3 := by
  unfold r{rid}Poly
  linear_combination ({lean_expr(e1)}) * h2 + ({lean_expr(e2)}) * hx + ({lean_expr(e3)}) * hy
""")
open('scratch/lean_polys.lean','w').write('\n'.join(out))
print('ok', sum(len(o) for o in out))
